// 网关统一鉴权：没有合法 token 直接拒绝，不转发到后端
function authGuard(token, next) {
  if (!token || !token.startsWith("Bearer ")) {
    return { status: 401, body: "missing token" };
  }
  const payload = token.slice(7);
  if (payload !== "valid-signature") {
    return { status: 403, body: "invalid token" };
  }
  return next(); // 放行
}

const ok = () => ({ status: 200, body: "from upstream" });
console.log(JSON.stringify(authGuard("Bearer valid-signature", ok)));
console.log(JSON.stringify(authGuard("Bearer bad", ok)));
console.log(JSON.stringify(authGuard("nothing", ok)));
